{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Intravenously administered [3H]-LY686017 localized in guinea pig brain by autoradiography, directly demonstrating BBB penetration; high transfer score strongly supports CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PD156707 crossed the blood-brain barrier in dogs with measurable CSF levels, providing direct CSF evidence of CNS exposure; transferable to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "KVA-D-88 achieved a brain/blood concentration ratio of about 0.6 in mice after systemic dosing and was classified as brain penetrant, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Altiratinib reached a brain:plasma ratio of 0.23 in mice after systemic dosing and was considered to significantly penetrate the murine blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CNP520 distributed to human CSF in a dose-proportional manner with CSF/plasma ratios similar to its unbound plasma fraction, confirming CNS penetration in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved analogues with high transfer scores show direct or in vivo evidence of BBB/CNS penetration, including autoradiography, CSF measurements, brain:plasma ratios, and human CSF data; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the query molecule itself.",
    "Efflux transporter involvement was not directly assessed for the query or most analogues.",
    "Some supporting analogues have moderate or low brain/plasma ratios, but they were still classified as brain penetrant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

